import sys

n = int(sys.stdin.read().split()[0])
out = []
for i in range(1, n + 1):
    row = []
    for j in range(n + 1):
        if i % 2 == 1:
            row.append(i if j < n else i + 1)
        else:
            row.append(i + 1 if j == 0 else i)
    out.append(' '.join(map(str, row)))
print('\n'.join(out))

